function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("show");clearTimeout(window.cartifyToastTimer);window.cartifyToastTimer=setTimeout(()=>t.classList.remove("show"),2200);}
function showCartifyModal({title,message,icon="✓",primaryText="OK",secondaryText="",onPrimary=()=>{},onSecondary=()=>{}}){const modal=$("#cartifyModal");$("#cartifyModalIcon").textContent=icon;$("#cartifyModalTitle").textContent=title;$("#cartifyModalMessage").textContent=message;const p=$("#cartifyModalPrimary"),s=$("#cartifyModalSecondary");p.textContent=primaryText;p.onclick=()=>{modal.classList.remove("show");onPrimary();};s.textContent=secondaryText;s.classList.toggle("hidden",!secondaryText);s.onclick=()=>{modal.classList.remove("show");onSecondary();};modal.classList.add("show");}
function openCartifyUpi(amount,orderId,packageName){history.pushState({cartifyPayment:true},"","#payment-pending");const upiUrl=makeUpiPaymentUrl(amount,orderId);if(packageName){const intentUrl="intent://pay?"+upiUrl.split("?")[1]+"#Intent;scheme=upi;package="+packageName+";end";window.location.href=intentUrl;}else{window.location.href=upiUrl;}}
function showUpiAppPicker(amount,orderId){let modal=document.getElementById("upiAppPicker");if(!modal){modal=document.createElement("div");modal.id="upiAppPicker";modal.style.cssText="position:fixed;inset:0;z-index:10050;background:rgba(10,15,30,.72);display:flex;align-items:center;justify-content:center;padding:18px;";modal.innerHTML='<div style="width:min(100%,390px);background:#fff;border-radius:22px;padding:22px;color:#172033;box-shadow:0 20px 70px #0005"><div style="font-size:12px;font-weight:800;letter-spacing:2px;color:#68738a">CARTIFY CHECKOUT</div><h2 style="margin:8px 0 5px;font-size:23px">Choose payment app</h2><p id="upiPickerAmount" style="margin:0 0 16px;color:#526078"></p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><button type="button" data-upi-app="com.phonepe.app" style="min-height:86px;padding:10px 8px;border:1px solid #e1e6ef;border-radius:14px;background:#f8f9fc;font-weight:800;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px"><img src="https://cdn.simpleicons.org/phonepe/5F259F" alt="PhonePe" width="38" height="38"><span>PhonePe</span></button><button type="button" data-upi-app="com.google.android.apps.nbu.paisa.user" style="min-height:86px;padding:10px 8px;border:1px solid #e1e6ef;border-radius:14px;background:#f8f9fc;font-weight:800;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px"><img src="https://cdn.simpleicons.org/googlepay/4285F4" alt="Google Pay" width="38" height="38"><span>Google Pay</span></button><button type="button" data-upi-app="net.one97.paytm" style="min-height:86px;padding:10px 8px;border:1px solid #e1e6ef;border-radius:14px;background:#f8f9fc;font-weight:800;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px"><img src="https://cdn.simpleicons.org/paytm/00BAF2" alt="Paytm" width="38" height="38"><span>Paytm</span></button><button type="button" data-upi-app="" style="min-height:86px;padding:10px 8px;border:1px solid #e1e6ef;border-radius:14px;background:#f8f9fc;font-weight:800;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px"><span style="font-size:34px">🏦</span><span>Other UPI apps</span></button></div><button id="upiPickerCancel" type="button" style="width:100%;margin-top:14px;padding:12px;border:0;border-radius:12px;background:#172033;color:white;font-weight:700">Cancel payment</button><p style="font-size:11px;color:#758096;margin:12px 0 0">Payment app khulne se payment confirm nahi hoti. Gateway verification abhi setup nahi hai; order create nahi hoga.</p></div>';document.body.appendChild(modal);}document.getElementById("upiPickerAmount").textContent="Pay "+money(amount)+" using your preferred UPI app.";modal.style.display="flex";modal.querySelectorAll("[data-upi-app]").forEach(b=>b.onclick=()=>{modal.style.display="none";openCartifyUpi(amount,orderId,b.dataset.upiApp||null);});document.getElementById("upiPickerCancel").onclick=()=>{modal.style.display="none";localStorage.removeItem("cartify_pending_upi");$("#checkoutMessage").textContent="Payment cancel hui. Koi order create nahi hua.";showView("checkoutView");};}
window.addEventListener("popstate",()=>{if(localStorage.getItem("cartify_pending_upi")){history.pushState({cartifyPayment:true},"","#payment-pending");showUpiReturnPrompt();}});
function showUpiReturnPrompt(){const pending=(()=>{try{return JSON.parse(localStorage.getItem("cartify_pending_upi")||"null");}catch{return null;}})();if(!pending||pending.userId!==currentUser?.uid)return;localStorage.removeItem("cartify_pending_upi");const modal=document.getElementById("upiAppPicker");if(modal)modal.style.display="none";$("#checkoutMessage").textContent="Payment app se wapas aa gaye. CARTIFY abhi payment ko verify nahi kar sakta, isliye order create nahi kiya gaya. Payment gateway verification setup hone ke baad hi order place hoga.";showView("checkoutView");}
window.addEventListener("focus",()=>setTimeout(showUpiReturnPrompt,350));
window.addEventListener("pageshow",()=>setTimeout(showUpiReturnPrompt,500));
function safe(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
let cartifyScrollFrame=0;function fastScrollTo(target){if(cartifyScrollFrame)cancelAnimationFrame(cartifyScrollFrame);const start=window.scrollY,distance=target-start;if(Math.abs(distance)<3){window.scrollTo(0,target);cartifyScrollFrame=0;return;}const duration=Math.min(360,Math.max(180,Math.abs(distance)*0.22));let started=0;function step(now){if(!started)started=now;const progress=Math.min(1,(now-started)/duration),ease=1-Math.pow(1-progress,3);window.scrollTo(0,start+distance*ease);if(progress<1)cartifyScrollFrame=requestAnimationFrame(step);else cartifyScrollFrame=0;}cartifyScrollFrame=requestAnimationFrame(step);}function scrollToElement(el){if(!el)return;const header=document.querySelector(".topbar"),offset=(header?.getBoundingClientRect().height||0)+16;const top=window.scrollY+el.getBoundingClientRect().top-offset;fastScrollTo(Math.max(0,top));}function scrollToElementAfterRender(selector){requestAnimationFrame(()=>scrollToElement($(selector)));}function showView(v){["authView","shopView","ordersView","cartView","checkoutView","adminView"].forEach(id=>$("#"+id).classList.add("hidden"));$("#"+v).classList.remove("hidden");fastScrollTo(0);}
function errorText(e){return ({"auth/invalid-credential":"Email or password is incorrect.","auth/email-already-in-use":"This email is already registered.","auth/weak-password":"Use at least 6 characters.","auth/popup-closed-by-user":"Google sign-in was closed."})[e.code]||e.message||"Something went wrong.";}
function setAuthMode(m){authMode=m;document.querySelectorAll("[data-auth]").forEach(b=>b.classList.toggle("active",b.dataset.auth===m));$("#nameLabel").classList.toggle("hidden",m!=="signup");$("#authName").required=m==="signup";$("#authSubmit").textContent=m==="signup"?"Create account":"Login";}
document.querySelectorAll("[data-auth]").forEach(b=>b.onclick=()=>setAuthMode(b.dataset.auth));
$("#authForm").onsubmit=async e=>{e.preventDefault();if(!auth){$("#authMessage").textContent="Firebase is not connected yet. Follow README setup.";return;}try{const email=$("#authEmail").value.trim(),pw=$("#authPassword").value;if(authMode==="signup"){const c=await createUserWithEmailAndPassword(auth,email,pw);await updateProfile(c.user,{displayName:$("#authName").value.trim()});}else await signInWithEmailAndPassword(auth,email,pw);}catch(err){$("#authMessage").textContent=errorText(err);}};
$("#googleBtn").onclick=async()=>{if(!auth){$("#authMessage").textContent="Firebase setup is required first.";return;}try{const provider=new GoogleAuthProvider();provider.setCustomParameters({prompt:"select_account"});await signInWithPopup(auth,provider);}catch(e){$("#authMessage").textContent=errorText(e)+" ("+(e.code||"")+")";}};
if(auth){onAuthStateChanged(auth,async u=>{currentUser=u;$("#accountBtn").textContent=u?(u.displayName||"Account"):"Sign in";const adminAllowed=!!u&&isAdmin();$("#adminMenuBtn")?.classList.toggle("hidden",!adminAllowed);$("#adminShortcut")?.classList.toggle("hidden",!adminAllowed);if(u){await loadCategories();await loadProducts();if(isAdmin())await openAdmin();else showView("shopView");setTimeout(showUpiReturnPrompt,700);}else showView("authView");});}
async function loadCategories(){if(!db||!currentUser)return;try{let snap=await getDocs(collection(db,"categories"));if(snap.empty&&isAdmin()){for(const name of ["Men","Women","Home","Accessories","Gadgets"])await addDoc(collection(db,"categories"),{name,createdAt:serverTimestamp()});snap=await getDocs(collection(db,"categories"));}categories=!snap.empty?snap.docs.map(d=>({id:d.id,name:d.data().name})).filter(c=>c.name).sort((x,y)=>x.name.localeCompare(y.name)):["Men","Women","Home","Accessories","Gadgets"].map(name=>({id:null,name}));}catch(e){console.warn(e);categories=["Men","Women","Home","Accessories","Gadgets"].map(name=>({id:null,name}));}renderCategories();}
function renderCategories(){const host=$("#categories");if(!host)return;host.innerHTML='<button class="category '+(activeCategory==="All"?"active":"")+'" data-category="All">All products</button>'+categories.map(c=>'<button class="category '+(activeCategory===c.name?"active":"")+'" data-category="'+safe(c.name)+'">'+safe(c.name)+'</button>').join("");host.querySelectorAll("[data-category]").forEach(b=>b.onclick=()=>{activeCategory=b.dataset.category;renderCategories();renderProducts();scrollToElement(document.querySelector(".product-head"));});}
async function addCategory(name){const clean=name.trim();if(!clean)return;if(categories.some(c=>c.name.toLowerCase()===clean.toLowerCase())){toast("Category already exists");return;}await addDoc(collection(db,"categories"),{name:clean,createdAt:serverTimestamp()});await loadCategories();renderAdminTab([]);toast("Category added");}
async function removeCategory(id,name){if(products.some(p=>p.category===name)){toast("Pehle products ko doosri category mein shift karo");return;}if(!id){toast("Category record missing; refresh karo");return;}if(!confirm('Remove category "'+name+'"?'))return;await deleteDoc(doc(db,"categories",id));if(activeCategory===name)activeCategory="All";await loadCategories();renderAdminTab([]);toast("Category removed");}
async function loadProducts(){try{const s=await getDocs(collection(db,"products"));if(!s.empty)products=s.docs.map(d=>({id:d.id,...d.data()}));}catch(e){console.warn(e);}renderProducts();}
let activeDetailProductId=null,detailGalleryIndex=0,pendingReviewImages=[];
function renderProducts(){const q=($("#searchInput").value||"").toLowerCase(),list=products.filter(p=>(activeCategory==="All"||p.category===activeCategory)&&String(p.name||"").toLowerCase().includes(q));$("#productGrid").innerHTML=list.map(p=>{const imgs=p.images?.length?p.images:[p.image].filter(Boolean);return '<article class="product-card" data-open-product="'+safe(p.id)+'"><div class="product-image"><img src="'+safe(imgs[0]||"")+'" alt="'+safe(p.name)+'" loading="lazy"></div>'+(imgs.length>1?'<div class="product-thumbs">'+imgs.map((im,i)=>'<img src="'+safe(im)+'" alt="Product view '+(i+1)+'">').join("")+'</div>':"")+'<div class="product-info"><div class="product-category">'+safe(p.category)+'</div><h3>'+safe(p.name)+'</h3><span class="price">'+money(p.price)+'</span> <span class="old-price">'+money(p.mrp||p.price)+'</span><p class="detail-hint">View photos, details & reviews →</p><div class="product-actions"><button class="add-btn" data-add="'+safe(p.id)+'">Add to Cart</button><button class="buy-btn" data-buy="'+safe(p.id)+'">Buy Now</button></div></div></article>'}).join("")||"<p>No products found.</p>";document.querySelectorAll("[data-add]").forEach(b=>b.onclick=e=>{e.stopPropagation();addToCart(b.dataset.add);});document.querySelectorAll("[data-buy]").forEach(b=>b.onclick=e=>{e.stopPropagation();buyNow(b.dataset.buy);});document.querySelectorAll("[data-open-product]").forEach(card=>card.onclick=e=>{if(e.target.closest("button"))return;openProductDetails(card.dataset.openProduct);});}
function openProductDetails(productId){const p=products.find(x=>x.id===productId);if(!p)return;activeDetailProductId=productId;detailGalleryIndex=0;pendingReviewImages=[];renderProductDetailContent(p);$("#productDetailModal").classList.add("show");document.body.classList.add("modal-open");}
function closeProductDetails(){$("#productDetailModal").classList.remove("show");document.body.classList.remove("modal-open");activeDetailProductId=null;}
function renderProductDetailContent(p){const host=$("#productDetailContent"),raw=Array.isArray(p.images)?p.images:(p.images?[p.images]:[]),imgs=raw.map(x=>typeof x==="string"?x:(x?.url||x?.src||"")).filter(Boolean);if(p.image&&!imgs.includes(p.image))imgs.unshift(p.image);if(!imgs.length)imgs.push("");const related=products.filter(x=>x.id!==p.id).slice(0,8);host.innerHTML='<button class="detail-close" id="closeProductDetail" aria-label="Close">×</button><div class="detail-main"><div class="detail-gallery"><div class="detail-photo-strip" id="detailPhotoStrip">'+imgs.map((im,i)=>'<div class="detail-photo-slide"><img src="'+safe(im)+'" alt="'+safe(p.name)+' photo '+(i+1)+'" loading="'+(i===0?'eager':'lazy')+'"></div>').join("")+'</div><div class="detail-photo-caption"><span>Swipe sideways to see all photos</span><b id="galleryCount">1 / '+imgs.length+'</b></div></div><section class="detail-related"><div class="eyebrow">DISCOVER MORE</div><h3>More products</h3><div class="related-grid">'+(related.map(x=>{const im=(Array.isArray(x.images)?x.images[0]:"")||x.image||"";return '<article class="related-card" data-related-product="'+safe(x.id)+'"><img src="'+safe(im)+'" alt="'+safe(x.name)+'"><b>'+safe(x.name)+'</b><span>'+money(x.price)+'</span></article>';}).join("")||"<p>More products coming soon.</p>")+'</div></section><div class="detail-product-info"><div class="product-category">'+safe(p.category||"")+'</div><h2>'+safe(p.name)+'</h2><div class="detail-price">'+money(p.price)+' <del>'+money(p.mrp||p.price)+'</del></div><p class="notice">'+imgs.length+' product photo(s) uploaded</p><div class="product-actions"><button class="add-btn" id="detailAddCart">Add to Cart</button><button class="buy-btn" id="detailBuyNow">Buy Now</button></div></div></div><section class="detail-reviews"><div class="eyebrow">CUSTOMER FEEDBACK</div><h3>Customer reviews</h3><div id="productReviewList" class="review-list"><p>Loading reviews…</p></div><form id="productReviewForm" class="review-form"><h4>Write a review</h4><label>Your rating<select name="rating" required><option value="">Select stars</option><option value="5">★★★★★ — Excellent</option><option value="4">★★★★☆ — Good</option><option value="3">★★★☆☆ — Average</option><option value="2">★★☆☆☆ — Poor</option><option value="1">★☆☆☆☆ — Very poor</option></select></label><label>Your review<textarea name="comment" rows="3" maxlength="600" placeholder="Share your experience…" required></textarea></label><label>Add review photos (up to 2)<input type="file" id="reviewPhotoFiles" accept="image/*" multiple></label><small id="reviewPhotoStatus" class="notice">You can attach up to 2 photos.</small><div id="reviewPhotoPreviews" class="review-photo-previews"></div><button class="primary full" type="submit">Submit review</button></form></section>';
$("#closeProductDetail").onclick=closeProductDetails;const strip=$("#detailPhotoStrip"),counter=$("#galleryCount");strip.addEventListener("scroll",()=>{const slideWidth=strip.clientWidth||1;const index=Math.min(imgs.length-1,Math.max(0,Math.round(strip.scrollLeft/slideWidth)));counter.textContent=(index+1)+" / "+imgs.length;},{passive:true});$("#detailAddCart").onclick=()=>addToCart(p.id);$("#detailBuyNow").onclick=()=>{closeProductDetails();buyNow(p.id);};host.querySelectorAll("[data-related-product]").forEach(el=>el.onclick=()=>renderProductDetailsAndScroll(el.dataset.relatedProduct));$("#reviewPhotoFiles").onchange=handleReviewPhotoChange;$("#productReviewForm").onsubmit=e=>submitProductReview(e,p);loadProductReviews(p.id);}
function renderProductDetailsAndScroll(id){openProductDetails(id);$("#productDetailModal").scrollTop=0;}
async function loadProductReviews(productId){const host=$("#productReviewList");try{const snap=await getDocs(query(collection(db,"reviews"),where("productId","==",productId)));const rows=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));if(!rows.length){host.innerHTML="<p>No reviews yet. Be the first to review this product.</p>";return;}const avg=rows.reduce((n,r)=>n+Number(r.rating||0),0)/rows.length;host.innerHTML='<div class="review-summary"><strong>★ '+avg.toFixed(1)+'/5</strong><span>'+rows.length+' review(s)</span></div>'+rows.map(r=>'<article class="review-card"><div class="review-card-head"><b>'+safe(r.userName||"CARTIFY customer")+'</b><span class="review-stars">'+("★".repeat(Math.max(0,Math.min(5,Number(r.rating)||0))))+("☆".repeat(5-Math.max(0,Math.min(5,Number(r.rating)||0))))+'</span></div><p>'+safe(r.comment||"")+'</p>'+(r.images?.length?'<div class="review-images">'+r.images.map(im=>'<img src="'+safe(im)+'" alt="Customer review photo">').join("")+'</div>':"")+'</article>').join("");}catch(err){console.error(err);host.innerHTML="<p>Reviews load nahi ho paaye. Firestore rules check karein.</p>";}}
async function compressReviewPhoto(file){if(!file||!file.type.startsWith("image/"))throw new Error("Image file choose karein.");const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error("Photo read nahi hui."));r.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const x=new Image();x.onload=()=>resolve(x);x.onerror=()=>reject(new Error("Photo open nahi hui."));x.src=src;});const scale=Math.min(1,800/Math.max(img.width,img.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);let q=.68,data=canvas.toDataURL("image/jpeg",q);while(data.length*.75>85*1024&&q>.3){q-=.08;data=canvas.toDataURL("image/jpeg",q);}if(data.length*.75>85*1024)throw new Error("Photo size zyada hai; chhoti photo choose karein.");return data;}
function renderReviewPhotoPreviews(){const host=$("#reviewPhotoPreviews");if(!host)return;host.innerHTML=pendingReviewImages.map((im,i)=>'<div class="review-photo-preview-item" style="position:relative;display:inline-block;width:112px;height:112px;margin:8px;border-radius:10px;overflow:visible"><img src="'+im+'" alt="Selected review photo '+(i+1)+'" style="display:block;width:112px;height:112px;object-fit:cover;border-radius:10px;border:1px solid #d7ddd9"><button type="button" data-remove-review-photo="'+i+'" aria-label="Remove photo" title="Remove photo" style="position:absolute!important;top:-7px!important;right:-7px!important;z-index:20!important;display:grid!important;place-items:center!important;width:25px!important;height:25px!important;min-width:25px!important;min-height:25px!important;padding:0!important;border:2px solid #fff!important;border-radius:50%!important;background:#d92d20!important;color:#fff!important;font-size:18px!important;font-weight:800!important;line-height:1!important;box-shadow:0 2px 7px #0005!important">×</button></div>').join("");host.querySelectorAll("[data-remove-review-photo]").forEach(b=>b.addEventListener("click",()=>{const index=Number(b.getAttribute("data-remove-review-photo"));if(Number.isInteger(index)&&index>=0&&index<pendingReviewImages.length){pendingReviewImages.splice(index,1);renderReviewPhotoPreviews();$("#reviewPhotoStatus").textContent=pendingReviewImages.length?pendingReviewImages.length+" photo(s) ready.":"You can attach up to 2 photos.";}}));}
async function handleReviewPhotoChange(e){const files=[...(e.target.files||[])];try{if(pendingReviewImages.length+files.length>2)throw new Error("Maximum 2 review photos.");const added=[];for(const f of files){const data=await compressReviewPhoto(f);pendingReviewImages.push(data);added.push(data);}const size=pendingReviewImages.reduce((n,x)=>n+x.length*.75,0);if(size>180*1024){pendingReviewImages.splice(pendingReviewImages.length-added.length,added.length);throw new Error("Photos ka total size 180 KB se kam rakhein.");}renderReviewPhotoPreviews();$("#reviewPhotoStatus").textContent=pendingReviewImages.length+" photo(s) ready. Galat photo hatane ke liye × dabayein.";}catch(err){toast(err.message);$("#reviewPhotoStatus").textContent=err.message;}finally{e.target.value="";}}
async function submitProductReview(e,p){e.preventDefault();if(!currentUser||!db){toast("Review dene ke liye login karein.");return;}const form=e.currentTarget,btn=form.querySelector('button[type="submit"]'),rating=Number(form.elements.rating.value),comment=form.elements.comment.value.trim();if(!rating||!comment){toast("Rating aur review likhna zaroori hai.");return;}btn.disabled=true;btn.textContent="Submitting…";try{const reviewId=p.id+"_"+currentUser.uid;await setDoc(doc(db,"reviews",reviewId),{productId:p.id,userId:currentUser.uid,userName:currentUser.displayName||currentUser.email?.split("@")[0]||"Customer",rating,comment,images:pendingReviewImages,updatedAt:serverTimestamp(),createdAt:serverTimestamp()},{merge:true});pendingReviewImages=[];form.reset();renderReviewPhotoPreviews();$("#reviewPhotoStatus").textContent="You can attach up to 2 photos.";toast("Review submitted. Thank you!");await loadProductReviews(p.id);}catch(err){console.error(err);toast("Review submit nahi hua: "+(err.message||"Firebase Rules check karein."));}finally{btn.disabled=false;btn.textContent="Submit review";}}


