function addToCart(id){const x=cart.find(i=>i.id===id);if(x)x.qty++;else cart.push({id,qty:1});saveCart();toast("Added to your cart");}
function buyNow(id){if(!currentUser){toast("Please sign in first");showView("authView");return;}cart=[{id,qty:1}];saveCart();renderCheckout();showView("checkoutView");}
function renderCart(){const rows=cart.map(x=>{const p=productFor(x);return p?'<div class="cart-row"><img src="'+safe(p.image)+'" alt=""><div class="grow"><b>'+safe(p.name)+'</b><p>'+money(p.price)+'</p></div><div class="qty-controls"><button data-minus="'+x.id+'">−</button><b>'+x.qty+'</b><button data-plus="'+x.id+'">+</button><button data-remove="'+x.id+'">×</button></div></div>':"";}).join("");$("#cartItems").innerHTML=rows||"<p>Your bag is empty. Find something you love in the shop.</p>";const total=cart.reduce((n,x)=>n+(productFor(x)?.price||0)*x.qty,0);$("#cartSummary").innerHTML=cart.length?'<div class="summary-line"><span>Product subtotal</span><b>'+money(total)+'</b></div><div class="summary-line"><span>Delivery fee (COD)</span><b>'+money(39)+'</b></div><div class="summary-line"><span>Delivery fee (UPI)</span><b>'+money(29)+'</b></div><p class="notice">Checkout par payment method choose karte hi uski delivery fee total mein add hogi.</p><button id="goCheckout" class="primary full">Continue to checkout</button>':"";$("#goCheckout")?.addEventListener("click",()=>{renderCheckout();showView("checkoutView");});document.querySelectorAll("[data-minus]").forEach(b=>b.onclick=()=>qty(b.dataset.minus,-1));document.querySelectorAll("[data-plus]").forEach(b=>b.onclick=()=>qty(b.dataset.plus,1));document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!==b.dataset.remove);saveCart();renderCart();});}
function qty(id,d){const x=cart.find(i=>i.id===id);if(x)x.qty+=d;cart=cart.filter(i=>i.qty>0);saveCart();renderCart();}
$("#cartBtn").onclick=()=>{if(!currentUser){showView("authView");return;}renderCart();showView("cartView");};
function closeAccountMenu(){const d=$("#accountDetails");if(d)d.removeAttribute("open");}
