$("#accountMenu")?.addEventListener("click",async e=>{const b=e.target.closest("[data-menu]");if(!b)return;const action=b.dataset.menu;closeAccountMenu();if(action==="orders"){await loadOrders();showView("ordersView");}else if(action==="shop"){showView("shopView");}else if(action==="profile"){toast((currentUser.displayName||"Customer")+" · "+(currentUser.email||""));}else if(action==="refer"){const shareText="Shop everyday finds on CARTIFY: "+location.href;if(navigator.share){try{await navigator.share({title:"CARTIFY",text:"Discover everyday shopping on CARTIFY",url:location.href});}catch(err){if(err.name!=="AbortError")toast("Sharing unavailable");}}else if(navigator.clipboard){try{await navigator.clipboard.writeText(shareText);toast("CARTIFY link copied. Share it with friends!");}catch{toast(shareText);}}else toast(shareText);}});
