function renderCheckout(){const subtotal=cart.reduce((n,x)=>n+(productFor(x)?.price||0)*x.qty,0),method=$("#checkoutForm").elements.payment.value,fee=method==="COD"?39:29,total=subtotal+fee;const bill='<div class="checkout-bill-inline" style="background:#f7f8fb;border:1px solid #dce3ed;border-radius:14px;padding:16px;margin:16px 0"><h3 style="margin:0 0 12px">Order bill</h3>'+cart.map(x=>'<div class="summary-line"><span>'+safe(productFor(x)?.name)+' × '+x.qty+'</span><b>'+money((productFor(x)?.price||0)*x.qty)+'</b></div>').join("")+'<div class="summary-line"><span>Product price</span><b>'+money(subtotal)+'</b></div><div class="summary-line"><span>Delivery fee ('+(method==="COD"?"COD":"UPI")+')</span><b>'+money(fee)+'</b></div><div class="summary-line total"><span>Total bill</span><b>'+money(total)+'</b></div>'+(method==="COD"?'<p class="notice">COD ke liye ₹39 delivery fee pehle UPI se pay hogi. Baaki '+money(subtotal)+' delivery par dena hai.</p>':'<p class="notice">Full UPI payment: '+money(total)+' (product + ₹29 delivery fee).</p>')+'</div>';let inline=$("#checkoutBillInline");if(!inline){inline=document.createElement("div");inline.id="checkoutBillInline";const submit=$("#checkoutForm").querySelector('button[type="submit"]');submit.parentNode.insertBefore(inline,submit);}inline.innerHTML=bill;$("#checkoutTotal").innerHTML=bill;if(currentUser)$("#checkoutForm").elements.name.value=currentUser.displayName||"";const submit=$("#checkoutForm").querySelector('button[type="submit"]');submit.textContent=method==="COD"?"Continue to pay ₹39 delivery fee":"Continue to choose payment app";document.querySelectorAll('input[name="payment"]').forEach(x=>x.onchange=renderCheckout);}
let cartifyMap=null,cartifyMarker=null,selectedMapPoint=null,leafletPromise=null;function loadLeaflet(){if(window.L)return Promise.resolve();if(leafletPromise)return leafletPromise;leafletPromise=new Promise((resolve,reject)=>{if(!document.getElementById("leafletCss")){const l=document.createElement("link");l.id="leafletCss";l.rel="stylesheet";l.href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";document.head.appendChild(l);}const s=document.createElement("script");s.src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";s.onload=resolve;s.onerror=()=>reject(new Error("Map load nahi hua"));document.head.appendChild(s);});return leafletPromise;}async function reverseMapPoint(lat,lon){const r=await fetch("https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&zoom=18&lat="+encodeURIComponent(lat)+"&lon="+encodeURIComponent(lon),{headers:{"Accept-Language":"en"}});if(!r.ok)throw new Error("Address lookup failed");return await r.json();}function mapSetPoint(lat,lon){selectedMapPoint={lat,lon};if(cartifyMarker)cartifyMarker.setLatLng([lat,lon]);else cartifyMarker=window.L.marker([lat,lon],{draggable:true}).addTo(cartifyMap);cartifyMarker.off("dragend").on("dragend",e=>{const p=e.target.getLatLng();mapSetPoint(p.lat,p.lng);});$("#mapSelectedAddress").textContent="Selected pin: "+lat.toFixed(5)+", "+lon.toFixed(5)+" · Use this pin to set delivery address."; }async function openAddressMap(){const modal=$("#addressMapModal");modal.classList.add("show");$("#mapSelectedAddress").textContent="Map par apne ghar ki exact location search ya pin drag karke select karein.";try{await loadLeaflet();if(!cartifyMap){cartifyMap=window.L.map("addressMap").setView([28.4089,77.3178],13);window.L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap"}).addTo(cartifyMap);cartifyMap.on("click",e=>mapSetPoint(e.latlng.lat,e.latlng.lng));}setTimeout(()=>cartifyMap.invalidateSize(),200);if(navigator.geolocation)navigator.geolocation.getCurrentPosition(p=>{cartifyMap.setView([p.coords.latitude,p.coords.longitude],17);mapSetPoint(p.coords.latitude,p.coords.longitude);},()=>{}, {enableHighAccuracy:true,timeout:12000,maximumAge:0});}catch(e){$("#mapSelectedAddress").textContent=e.message;}}$("#useCurrentLocation").onclick=openAddressMap;$("#mapSearchBtn").onclick=async()=>{const q=$("#mapSearchInput").value.trim();if(!q)return;$("#mapSelectedAddress").textContent="Address search ho raha hai…";try{const r=await fetch("https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=5&q="+encodeURIComponent(q));const d=await r.json();if(!d.length)throw new Error("Address nahi mila. Nearby landmark ya area search karein.");cartifyMap.setView([Number(d[0].lat),Number(d[0].lon)],18);mapSetPoint(Number(d[0].lat),Number(d[0].lon));}catch(e){$("#mapSelectedAddress").textContent=e.message;}};$("#mapUseGps").onclick=()=>{if(!navigator.geolocation)return;$("#mapSelectedAddress").textContent="GPS location mil rahi hai…";navigator.geolocation.getCurrentPosition(p=>{cartifyMap.setView([p.coords.latitude,p.coords.longitude],18);mapSetPoint(p.coords.latitude,p.coords.longitude);},()=>{$("#mapSelectedAddress").textContent="GPS permission/location unavailable. Search karke pin select karein."},{enableHighAccuracy:true,timeout:15000,maximumAge:0});};$("#mapConfirmLocation").onclick=async()=>{if(!selectedMapPoint){$("#mapSelectedAddress").textContent="Pehle map par apna ghar select karein.";return;}const btn=$("#mapConfirmLocation");btn.disabled=true;try{const d=await reverseMapPoint(selectedMapPoint.lat,selectedMapPoint.lon),a=d.address||{},district=a.state_district||a.county||a.city_district||"",city=a.city||a.town||a.village||a.municipality||a.suburb||"",area=[a.neighbourhood,a.suburb,a.residential,a.road].filter(Boolean).filter((v,i,x)=>x.indexOf(v)===i).join(", ");if(a.postcode)$("#pincode").value=a.postcode;if(a.state)$("#state").value=a.state;if(district)$("#district").value=district;if(city)$("#checkoutForm").elements.city.value=city;if(a.house_number)$("#checkoutForm").elements.house.value=a.house_number;if(area)$("#checkoutForm").elements.area.value=area;$("#postOffice").value="";$("#locationStatus").textContent="Map par select ki gayi location ke hisab se address fill hua. House/flat aur post office verify karein.";$("#addressMapModal").classList.remove("show");}catch(e){$("#mapSelectedAddress").textContent="Address details nahi mil paayi. Pin thoda adjust karke try karein.";}finally{btn.disabled=false;}};$("#mapCloseBtn").onclick=()=>$("#addressMapModal").classList.remove("show");
$("#checkoutForm").onsubmit=async e=>{e.preventDefault();if(!currentUser||!db){$("#checkoutMessage").textContent="Please sign in and complete Firebase setup.";return;}if(!cart.length)return;const f=new FormData(e.currentTarget),paymentMethod=f.get("payment");if(!["COD","UPI"].includes(paymentMethod)){toast("Payment method choose karein.");return;}const items=cart.map(x=>{const p=productFor(x);return{productId:x.id,name:p.name,quantity:x.qty,unitPrice:p.price,costPrice:Number(p.costPrice||0),lineTotal:p.price*x.qty};}),subtotal=items.reduce((n,x)=>n+x.lineTotal,0),deliveryFee=paymentMethod==="COD"?39:29,total=subtotal+deliveryFee,paymentAmount=paymentMethod==="COD"?39:total;const orderData={userId:currentUser.uid,email:currentUser.email||"",customer:{name:f.get("name"),mobile:f.get("mobile"),alternate:f.get("alternate"),pincode:f.get("pincode"),state:f.get("state"),district:f.get("district"),postOffice:f.get("postOffice"),city:f.get("city"),house:f.get("house"),area:f.get("area"),landmark:f.get("landmark"),addressType:f.get("addressType")},items,subtotal,deliveryFee,total,paymentMethod,balanceDue:paymentMethod==="COD"?subtotal:0,status:"Pending Approval",approvalStatus:"Pending"};const pending={userId:currentUser.uid,prompted:false,paymentPurpose:paymentMethod==="COD"?"COD_DELIVERY_FEE":"FULL_UPI",amount:paymentAmount,orderData};localStorage.setItem("cartify_pending_upi",JSON.stringify(pending));$("#checkoutMessage").textContent=paymentMethod==="COD"?"Pehle ₹39 delivery fee pay karein. Payment ke bina COD order place nahi hoga.":"Poora bill UPI se pay karein. Payment ke bina order submit nahi hoga.";showUpiAppPicker(paymentAmount,"CARTIFY-"+Date.now());};async function loadOrders(){if(!db||!currentUser)return;const s=await getDocs(query(collection(db,"orders"),where("userId","==",currentUser.uid))),a=s.docs.map(d=>({id:d.id,...d.data()})).sort((x,y)=>(y.createdAt?.seconds||0)-(x.createdAt?.seconds||0));$("#ordersList").innerHTML=a.map(o=>'<div class="order-card"><div class="grow"><b>Order #'+o.id.slice(0,8).toUpperCase()+'</b><p>'+o.items.map(i=>safe(i.name)+" × "+i.quantity).join(", ")+'</p><p>Product amount: <b>'+money(o.subtotal??o.total)+'</b><br>Delivery fee: <b>'+money(o.deliveryFee||0)+'</b><br>Total bill: <b>'+money(o.total)+'</b>'+(o.paymentMethod==="COD"?"<br>Delivery fee advance: "+money(o.deliveryFee||0)+" · Balance on delivery: "+money(o.balanceDue||o.subtotal||0):"")+'</p><small>'+safe(o.status)+' · '+safe(o.paymentMethod)+' · Payment: '+safe(o.paymentStatus||"Pending")+'</small></div></div>').join("")||"<p>You have not placed any orders yet.</p>";}
function isAdmin(){return !!currentUser&&ADMIN_EMAILS.map(x=>x.toLowerCase().trim()).includes((currentUser.email||"").toLowerCase().trim());}
