$("#adminLogout").onclick=()=>showView("shopView");
async function renderAdmin(){const s=await getDocs(collection(db,"orders")),all=s.docs.map(d=>({id:d.id,...d.data()}));const delivered=all.filter(o=>o.status==="Delivered"),sales=delivered.reduce((n,o)=>n+Number(o.total||0),0),profit=delivered.reduce((n,o)=>n+(o.items||[]).reduce((m,i)=>m+(Number(i.unitPrice||0)-Number(i.costPrice||0))*Number(i.quantity||0),0),0);$("#adminStats").innerHTML='<div class="stat">Delivered orders<strong>'+delivered.length+'</strong></div><div class="stat">Successful sales<strong>'+money(sales)+'</strong></div><div class="stat">Net product margin<strong>'+money(profit)+'</strong></div><div class="stat">Awaiting approval<strong>'+all.filter(o=>!o.approvalStatus||o.approvalStatus==="Pending"||o.status==="Pending Approval").length+'</strong></div>';renderAdminTab(all); }
async function setOrderDecision(orderId,decision){const next=decision==="accept"?"Approved":"Rejected";const decisionPatch={status:next,approvalStatus:next,decisionAt:new Date()};if(next==="Rejected")decisionPatch.rejectedAt=serverTimestamp();await updateDoc(doc(db,"orders",orderId),decisionPatch);if(SHEETS_WEB_APP_URL){try{await fetch(SHEETS_WEB_APP_URL,{method:"POST",mode:"no-cors",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({action:"update",orderId,status:next})});}catch(e){console.warn("Sheet status sync failed",e);}}toast(decision==="accept"?"Order accepted":"Order rejected");await renderAdmin();}
function toDateValue(v){if(!v)return null;const d=typeof v.toDate==="function"?v.toDate():v instanceof Date?v:new Date(v);return Number.isNaN(d.getTime())?null:d;}
function deliveredProfit(o){return (o.items||[]).reduce((m,i)=>m+(Number(i.unitPrice||0)-Number(i.costPrice||0))*Number(i.quantity||0),0);}
function renderEarnings(all){const now=new Date(),monthKey=now.getFullYear()+"-"+String(now.getMonth()+1).padStart(2,"0"),byMonth={},byYear={};const bucket=()=>({generated:0,successful:0,sales:0,profit:0});all.forEach(o=>{const created=toDateValue(o.createdAt);if(created){const mk=created.getFullYear()+"-"+String(created.getMonth()+1).padStart(2,"0"),yk=String(created.getFullYear());if(!byMonth[mk])byMonth[mk]=bucket();if(!byYear[yk])byYear[yk]=bucket();byMonth[mk].generated++;byYear[yk].generated++;}if(o.status==="Delivered"){const delivered=toDateValue(o.deliveredAt)||created;if(!delivered)return;const mk=delivered.getFullYear()+"-"+String(delivered.getMonth()+1).padStart(2,"0"),yk=String(delivered.getFullYear());if(!byMonth[mk])byMonth[mk]=bucket();if(!byYear[yk])byYear[yk]=bucket();[byMonth[mk],byYear[yk]].forEach(x=>{x.successful++;x.sales+=Number(o.total||0);x.profit+=deliveredProfit(o);});}});const current=byMonth[monthKey]||bucket(),allTime=all.filter(o=>o.status==="Delivered").reduce((x,o)=>({successful:x.successful+1,sales:x.sales+Number(o.total||0),profit:x.profit+deliveredProfit(o)}),{successful:0,sales:0,profit:0});const monthRows=Object.keys(byMonth).sort().reverse().map(k=>{const [y,m]=k.split("-");const label=new Date(Number(y),Number(m)-1,1).toLocaleDateString("en-IN",{month:"long",year:"numeric"}),x=byMonth[k];return '<tr><td>'+label+'</td><td>'+x.generated+'</td><td>'+x.successful+'</td><td>'+money(x.sales)+'</td><td>'+money(x.profit)+'</td></tr>';}).join("");const yearRows=Object.keys(byYear).sort().reverse().map(y=>{const x=byYear[y];return '<tr><td>'+y+'</td><td>'+x.generated+'</td><td>'+x.successful+'</td><td>'+money(x.sales)+'</td><td>'+money(x.profit)+'</td></tr>';}).join("");$("#adminContent").innerHTML='<section class="earnings-current"><h3>Current month · '+now.toLocaleDateString("en-IN",{month:"long",year:"numeric"})+'</h3><div class="stats"><div class="stat">Orders generated<strong>'+current.generated+'</strong></div><div class="stat">Successful / delivered<strong>'+current.successful+'</strong></div><div class="stat">Sales this month<strong>'+money(current.sales)+'</strong></div><div class="stat">Profit this month<strong>'+money(current.profit)+'</strong></div></div><p class="notice">Har naye month mein current-month counters automatically ₹0 se start hote hain. Purane months ke records safe rehte hain. Sales/profit sirf Delivered orders se count hote hain.</p></section><h3>All-time totals</h3><div class="stats"><div class="stat">Total orders<strong>'+all.length+'</strong></div><div class="stat">Successful orders<strong>'+allTime.successful+'</strong></div><div class="stat">Total delivered sales<strong>'+money(allTime.sales)+'</strong></div><div class="stat">Total delivered profit<strong>'+money(allTime.profit)+'</strong></div></div><h3>Month-wise report</h3><div class="table-scroll"><table class="earnings-table"><thead><tr><th>Month</th><th>Orders generated</th><th>Successful</th><th>Sales</th><th>Profit</th></tr></thead><tbody>'+monthRows+'</tbody></table></div><h3>Year-wise report</h3><div class="table-scroll"><table class="earnings-table"><thead><tr><th>Year</th><th>Orders generated</th><th>Successful</th><th>Sales</th><th>Profit</th></tr></thead><tbody>'+yearRows+'</tbody></table></div>';}
function renderAdminTab(all=[]){if(adminTab==="products"){$("#adminContent").innerHTML='<section class="admin-panel product-create-panel"><div class="eyebrow">CATALOGUE MANAGEMENT</div><h2>Add New Product</h2><p class="notice">Create or update a product listing.</p><form id="productForm" class="checkout-form"><input type="hidden" name="productId"><div class="two-col"><label>Product name<input name="name" required></label><label>Category<select name="category">'+categories.map(c=>'<option value="'+safe(c.name)+'">'+safe(c.name)+'</option>').join("")+'</select></label></div><div class="two-col"><label>Selling price<input name="price" type="number" min="1" required></label><label>Purchase cost (Meesho)<input name="costPrice" type="number" min="0" required></label></div><div class="image-upload-box"><label>Choose product photo from phone gallery<input type="file" id="productPhotoFile" accept="image/*" multiple></label><small id="imageUploadStatus" class="notice">Select multiple photos at once. Up to 6 gallery photos; each is compressed automatically.</small><div id="productPhotoPreviews" class="product-upload-previews"></div></div><div id="imageInputs"><label>Or add image URL 1 (optional)<input type="url" name="productImageUrls" placeholder="https://example.com/image.jpg"></label></div><button type="button" class="outline-btn" id="addImageInput">+ Add another image URL</button><p class="notice">No Cloudinary or paid image service is used. Gallery photos are compressed and saved with the product.</p><button class="primary full" id="saveProductBtn">Add product</button><button type="button" class="outline-btn hidden" id="cancelEditProduct">Cancel edit</button></form></section><section class="admin-panel category-panel"><div class="eyebrow">STORE STRUCTURE</div><h2>Manage Categories</h2><form id="categoryForm" class="checkout-form"><label>New category name<input name="categoryName" placeholder="e.g. Kids" required></label><button class="primary" type="submit">+ Add category</button></form><div class="admin-order">'+categories.map(c=>'<div class="decision-actions"><b>'+safe(c.name)+'</b><button type="button" class="secondary" data-remove-category="'+safe(c.id||"")+'" data-category-name="'+safe(c.name)+'">Remove</button></div>').join("")+'</div></section><section class="admin-panel catalogue-panel"><div class="eyebrow">YOUR INVENTORY</div><h2>Product Catalogue · '+products.length+' items</h2><div id="productCatalogue">'+products.map(p=>'<div class="admin-order"><b>'+safe(p.name)+'</b><p>'+safe(p.category)+' · '+money(p.price)+'</p><button class="outline-btn" data-edit-product="'+safe(p.id)+'">Edit product</button></div>').join("")+'</div></section>';$("#categoryForm").onsubmit=async e=>{e.preventDefault();try{await addCategory(new FormData(e.currentTarget).get("categoryName"));}catch(err){console.error(err);toast("Category add failed: "+errorText(err));}};document.querySelectorAll("[data-remove-category]").forEach(b=>b.onclick=async()=>{try{await removeCategory(b.dataset.removeCategory,b.dataset.categoryName);}catch(err){console.error(err);toast("Category remove failed: "+errorText(err));}});let imageNo=1;$("#addImageInput").onclick=()=>{imageNo++;const wrap=document.createElement("label");wrap.textContent="Product image URL "+imageNo;const input=document.createElement("input");input.type="url";input.name="productImageUrls";input.placeholder="https://example.com/image.jpg";wrap.appendChild(input);$("#imageInputs").appendChild(wrap);scrollToElement(wrap);input.focus({preventScroll:true});};$("#cancelEditProduct").onclick=()=>{const form=$("#productForm");form.reset();form.elements.productId.value="";$("#imageInputs").innerHTML='<label>Or add image URL 1 (optional)<input type="url" name="productImageUrls" placeholder="https://example.com/image.jpg"></label>';$("#productPhotoFile").value="";pendingGalleryImages=[];renderUploadPreviews();$("#imageUploadStatus").textContent="Select multiple photos at once. Up to 6 gallery photos; each is compressed automatically.";imageNo=1;$("#saveProductBtn").textContent="Add product";$("#cancelEditProduct").classList.add("hidden");};document.querySelectorAll("[data-edit-product]").forEach(b=>b.onclick=()=>{const p=products.find(x=>x.id===b.dataset.editProduct);if(!p)return;const form=$("#productForm");form.elements.productId.value=p.id;form.elements.name.value=p.name||"";form.elements.category.value=p.category||"Men";form.elements.price.value=p.price||"";form.elements.costPrice.value=p.costPrice||0;const imgs=p.images?.length?p.images:[p.image].filter(Boolean);pendingGalleryImages=imgs.filter(x=>String(x).startsWith("data:image/"));$("#productPhotoFile").value="";renderUploadPreviews();$("#imageUploadStatus").textContent=pendingGalleryImages.length+" saved gallery photo(s). Select more to add.";const urlImgs=imgs.filter(x=>!String(x).startsWith("data:image/"));$("#imageInputs").innerHTML="";(urlImgs.length?urlImgs:[""]).forEach((url,i)=>{const wrap=document.createElement("label");wrap.textContent="Product image URL "+(i+1);const input=document.createElement("input");input.type="url";input.name="productImageUrls";input.placeholder="https://example.com/image.jpg";input.value=url;wrap.appendChild(input);$("#imageInputs").appendChild(wrap);});imageNo=urlImgs.length||1;$("#saveProductBtn").textContent="Save product changes";$("#cancelEditProduct").classList.remove("hidden");scrollToElement(form);});let pendingGalleryImages=[];function renderUploadPreviews(){const host=$("#productPhotoPreviews");if(!host)return;host.innerHTML=pendingGalleryImages.map((src,i)=>'<div class="upload-preview-item"><img src="'+src+'" alt="Product photo '+(i+1)+'"><button type="button" data-remove-upload="'+i+'" aria-label="Remove photo">×</button></div>').join("");host.querySelectorAll("[data-remove-upload]").forEach(b=>b.onclick=()=>{pendingGalleryImages.splice(Number(b.dataset.removeUpload),1);renderUploadPreviews();$("#imageUploadStatus").textContent=pendingGalleryImages.length+" gallery photo(s) selected.";});}async function compressProductPhoto(file){if(!file||!file.type.startsWith("image/"))throw new Error("Please choose image files only.");const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error("Could not read image."));reader.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(new Error("Could not open image."));el.src=source;});const scale=Math.min(1,900/Math.max(img.width,img.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);let quality=.72,result=canvas.toDataURL("image/jpeg",quality);while(result.length*.75>90*1024&&quality>.28){quality-=.07;result=canvas.toDataURL("image/jpeg",quality);}if(result.length*.75>90*1024)throw new Error("Photo could not be compressed enough. Choose a smaller image.");return result;}$("#productPhotoFile").onchange=async e=>{const files=[...(e.target.files||[])];if(!files.length)return;try{if(pendingGalleryImages.length+files.length>6)throw new Error("Maximum 6 gallery photos per product.");$("#imageUploadStatus").textContent="Compressing "+files.length+" photo(s)…";const added=[];for(const file of files){const data=await compressProductPhoto(file);pendingGalleryImages.push(data);added.push(data);renderUploadPreviews();}const totalBytes=pendingGalleryImages.reduce((n,x)=>n+x.length*.75,0);if(totalBytes>650*1024){pendingGalleryImages.splice(pendingGalleryImages.length-added.length,added.length);renderUploadPreviews();throw new Error("Photos exceed the safe 650 KB total. Choose fewer or smaller photos.");}$("#imageUploadStatus").textContent=pendingGalleryImages.length+" gallery photo(s) ready · "+Math.round(totalBytes/1024)+" KB total.";}catch(err){$("#imageUploadStatus").textContent=err.message;toast(err.message);}finally{e.target.value="";}};$("#productForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),urls=[...e.currentTarget.querySelectorAll('input[name="productImageUrls"]')].map(x=>x.value.trim()).filter(Boolean);if(urls.some(u=>!/^https:\/\//i.test(u))){toast("Image URL https:// se start hona chahiye");return;}const id=f.get("productId"),btn=$("#saveProductBtn");btn.disabled=true;btn.textContent="Saving product…";try{const totalBytes=pendingGalleryImages.reduce((n,x)=>n+x.length*.75,0);if(pendingGalleryImages.length>6||totalBytes>650*1024)throw new Error("Maximum 6 gallery photos and 650 KB total.");const images=[...pendingGalleryImages,...urls];if(!images.length)throw new Error("Choose gallery photos or add at least one image URL.");const data={name:f.get("name").trim(),category:f.get("category"),price:Number(f.get("price")),mrp:Number(f.get("price")),costPrice:Number(f.get("costPrice")),image:images[0],images,active:true};if(id)await updateDoc(doc(db,"products",id),data);else await addDoc(collection(db,"products"),data);await loadProducts();await renderAdmin();toast(id?"Product updated successfully":"Product added successfully");}catch(err){toast("Could not save product: "+err.message);btn.disabled=false;btn.textContent=id?"Save product changes":"Add product";}};return;}if(adminTab==="earnings"){renderEarnings(all);return;}const filtered=adminTab==="pending"?all.filter(o=>["Pending Approval","New","Pending"].includes(o.status)):adminTab==="approved"?all.filter(o=>(o.approvalStatus==="Approved"||o.status==="Approved"||o.status==="Accepted"||["Processing","Shipped"].includes(o.status))&&o.status!=="Delivered"):adminTab==="rejected"?all.filter(o=>o.status==="Rejected"||o.approvalStatus==="Rejected"):all.filter(o=>o.status==="Delivered");$("#adminContent").innerHTML=filtered.map(o=>'<div class="admin-order"><b>Order #'+o.id.slice(0,8).toUpperCase()+' · '+money(o.total)+'</b><p><strong>'+safe(o.status||"Pending Approval")+'</strong> · '+safe(o.paymentMethod)+' · Payment: '+safe(o.paymentStatus)+'</p><p>Product: '+money(o.subtotal??o.total)+' · Delivery fee: '+money(o.deliveryFee||0)+' · Total: '+money(o.total)+' · COD balance: '+money(o.balanceDue||0)+'</p><p>'+safe(o.customer?.name)+' · '+safe(o.customer?.mobile)+' · '+safe(o.customer?.alternate)+' · PIN '+safe(o.customer?.pincode)+'</p><p>'+safe(o.customer?.house)+', '+safe(o.customer?.area)+', '+safe(o.customer?.landmark)+', '+safe(o.customer?.city)+', '+safe(o.customer?.district)+', '+safe(o.customer?.state)+'</p><p>'+o.items.map(i=>safe(i.name)+" × "+i.quantity+" · "+money(i.unitPrice)).join("<br>")+'</p>'+((["Pending Approval","New","Pending"].includes(o.status))?'<div class="decision-actions"><button class="primary" data-accept="'+o.id+'">Accept order</button><button class="secondary" data-reject="'+o.id+'">Reject order</button></div>':(o.status!=="Rejected"?'<label>Order status <select data-status="'+o.id+'">'+["Approved","Processing","Shipped","Delivered"].map(v=>'<option '+(o.status===v?"selected":"")+'>'+v+'</option>').join("")+'</select></label>':'<p>Order rejected</p>'))+'</div>').join("")||"<p>No orders yet.</p>";document.querySelectorAll("[data-accept]").forEach(b=>b.onclick=()=>setOrderDecision(b.dataset.accept,"accept"));document.querySelectorAll("[data-reject]").forEach(b=>b.onclick=()=>setOrderDecision(b.dataset.reject,"reject"));document.querySelectorAll("[data-status]").forEach(x=>x.onchange=async()=>{const patch={status:x.value};if(x.value==="Delivered")patch.deliveredAt=serverTimestamp();await updateDoc(doc(db,"orders",x.dataset.status),patch);if(SHEETS_WEB_APP_URL){try{await fetch(SHEETS_WEB_APP_URL,{method:"POST",mode:"no-cors",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({action:"update",orderId:x.dataset.status,status:x.value})});}catch(e){console.warn(e);}}toast("Order status updated");await renderAdmin();});}
document.querySelectorAll("[data-admin]").forEach(b=>b.onclick=async()=>{adminTab=b.dataset.admin;document.querySelectorAll("[data-admin]").forEach(x=>x.classList.toggle("active",x===b));const s=await getDocs(collection(db,"orders"));renderAdminTab(s.docs.map(d=>({id:d.id,...d.data()})));scrollToElementAfterRender("#adminContent");});
